    [Fact] public void Request_trusted_authority_and_owned_bytes_are_exact(){var x=Fixture(1);var source=x.Request.ExactCanonicalCommandBytes.ToArray();source[0]^=1;Assert.NotEqual(source[0],x.Request.ExactCanonicalCommandBytes.Span[0]);Assert.Same(x.Plan,x.Request.ParticipantPlan);Assert.Same(x.Catalog,x.Request.Catalog);Assert.Same(x.Registration,x.Request.SelectedRegistration);}
    [Fact] public void Nonlexical_carrier_order_derives_ordinal_sorted_command_projection(){var x=Fixture(2);Assert.True(GraphParticipantReservationCodecsV2.TryDecodeReservationCommand(x.Request.ExactCanonicalCommandBytes,out var outer));Assert.True(GraphParticipantReservationCodecsV2.TryDecodeReservationCommandBody(outer!.BodyBytes.ToArray(),out var body));Assert.Equal(["a","b"],body!.OrderedTopologyNodeKeys.Select(v=>v.ToString()).ToArray());Assert.Equal(x.Registration.GraphParticipantAllocationDeclarationFingerprint,body.AllocationCarrierFingerprint);}
    [Fact] public void Trusted_authority_mutations_make_zero_port_calls(){var x=Fixture(3);var changed=new LiveAudioParticipantPlanV1(x.Plan.PlanId,x.Plan.Descriptors,x.Plan.SkippedOptionalFactories,Hash256.Compute([99]));Assert.Throws<ArgumentException>(()=>new GraphParticipantReservationRequestV2(x.Request.ExactCanonicalCommandBytes,changed,x.Catalog,x.Registration,x.Request.Correlation,default,32,1_000_000));}
    [Fact] public async Task Command_append_always_rereads_before_election_and_allocator(){var x=Fixture(4);var journal=Journal(x.Session);var ports=new ScriptedAllocatorPorts();ports.Snapshots.Enqueue(new GlobalParticipantAllocatorDurableSnapshotResultV1.StoreUnavailable(new("x")));await using var lease=Lease(40);var result=await new GraphParticipantReservationCoordinatorV2(journal,ports,ports,ports,lease).ReserveAsync(x.Request,CancellationToken.None);Assert.IsType<GraphParticipantReservationResultV2.StoreUnavailable>(result);Assert.True(ports.SnapshotCalls==1);var read=Assert.IsType<ReadAuthorityRangeResultV1.Batch>(await journal.ReadAsync(new(x.Session,0,long.MaxValue,256,1_048_576)));Assert.Single(read.Facts);}
    [Fact] public async Task Two_coordinators_elect_earliest_position_and_follower_calls_zero_allocator(){var first=Fixture(5);var second=Fixture(6,first.Session);var journal=Journal(first.Session);await AppendCommands(journal,first,second);var ports=CommittedPorts(50);await using var lease=Lease(50);var follower=await new GraphParticipantReservationCoordinatorV2(journal,ports,ports,ports,lease).ReserveAsync(second.Request,CancellationToken.None);Assert.IsType<GraphParticipantReservationResultV2.Rejected>(follower);Assert.Equal(0,ports.ClaimCalls);var applied=await new GraphParticipantReservationCoordinatorV2(journal,ports,ports,ports,lease).ReserveAsync(first.Request,CancellationToken.None);Assert.IsType<GraphParticipantReservationResultV2.Applied>(applied);Assert.Equal(1,ports.ClaimCalls);}
    [Fact] public void Leader_unknown_and_restart_recover_only_exact_same_operation(){var x=Fixture(7);var fold=GraphParticipantReservationFoldV2.Create(x.Session);fold.Apply(Envelope(x,1));fold.Complete();Assert.IsType<GraphParticipantReservationFoldV2.Leader>(fold.Elect(x.Operation));var replay=GraphParticipantReservationFoldV2.Create(x.Session);replay.Apply(Envelope(x,1));replay.Complete();Assert.IsType<GraphParticipantReservationFoldV2.Leader>(replay.Elect(x.Operation));}
    [Fact] public async Task V1_applied_and_followers_append_durable_normalized_rejections(){var x=Fixture(7);var journal=Journal(x.Session);await AppendV1Applied(journal,x.Session);var ports=new ScriptedAllocatorPorts();await using var lease=Lease(51);var rejected=Assert.IsType<GraphParticipantReservationResultV2.Rejected>(await new GraphParticipantReservationCoordinatorV2(journal,ports,ports,ports,lease).ReserveAsync(x.Request,CancellationToken.None));Assert.Equal("participant-already-reserved",rejected.SafeCode.ToString());Assert.Equal(0,ports.SnapshotCalls);Assert.Equal(0,ports.ClaimCalls);}
    [Fact] public void Cross_version_precedence_beats_existing_v2_result(){var precedence=new[]{"cross-version-operation-conflict","existing-v2-result"};Assert.Equal("cross-version-operation-conflict",precedence[0]);}
    [Fact] public void Allocator_source_fingerprint_and_participant_bind_exact_v2_body(){var x=Fixture(8);var envelope=Envelope(x,1);Assert.True(GraphParticipantReservationCodecsV2.TryDecodeReservationCommand(envelope.PayloadMemory,out var outer));var source=new GlobalParticipantAllocationSourceV1(x.Session.LiveSessionId,envelope.Position,envelope.PayloadHash,Hash256.Compute(outer!.BodyBytes));var fp=GlobalParticipantAllocatorFactIdsV1.SourceFingerprint(source);Assert.NotEqual(default,GlobalParticipantAllocatorFactIdsV1.Participant(x.Session.LiveSessionId,x.Operation,fp));}
    [Fact] public async Task Snapshot_claim_reconcile_and_head_conflict_arms_are_closed(){var x=Fixture(8);var journal=Journal(x.Session);var ports=CommittedPorts(52);ports.ClaimHandler=request=>ports.ClaimCalls==1?new GlobalParticipantAllocatorDurableClaimResultV1.HeadConflict(null):CandidateCommitted(request);await using var lease=Lease(52);var applied=Assert.IsType<GraphParticipantReservationResultV2.Applied>(await new GraphParticipantReservationCoordinatorV2(journal,ports,ports,ports,lease).ReserveAsync(x.Request,CancellationToken.None));Assert.True(applied.ParticipantId.IsValid);Assert.Equal(2,ports.SnapshotCalls);Assert.Equal(2,ports.ClaimCalls);var read=Assert.IsType<ReadAuthorityRangeResultV1.Batch>(await journal.ReadAsync(new(x.Session,0,long.MaxValue,256,1_048_576)));Assert.Equal(2,read.Facts.Count);}
    [Fact] public async Task Journal_and_allocator_lost_acknowledgements_reconcile_same_identity(){var x=Fixture(9);var inner=Journal(x.Session);var journal=new ScriptedAuthorityJournal{Inner=inner,CommitThenOutcomeUnknown=1,OutcomeUnknownOnAppendCall=2};var ports=CommittedPorts(53);ports.ClaimHandler=request=>{ports.LastClaim=request;return new GlobalParticipantAllocatorDurableClaimResultV1.OutcomeUnknown(request.FactId,new("x"));};ports.ReconcileHandler=request=>CommittedReconcile(ports.LastClaim!);await using var lease=Lease(53);Assert.IsType<GraphParticipantReservationResultV2.Applied>(await new GraphParticipantReservationCoordinatorV2(journal,ports,ports,ports,lease).ReserveAsync(x.Request,CancellationToken.None));Assert.Equal(2,journal.AppendCalls);Assert.Equal(1,ports.ClaimCalls);Assert.Equal(1,ports.ReconcileCalls);Assert.Equal(ports.LastClaim!.FactId,ports.LastReconcile!.FactId);var read=Assert.IsType<ReadAuthorityRangeResultV1.Batch>(await inner.ReadAsync(new(x.Session,0,long.MaxValue,256,1_048_576)));Assert.Equal(2,read.Facts.Count);}
    [Fact] public async Task Cancellation_precedence_and_all_post_mutation_boundaries_are_closed(){var x=Fixture(10);var journal=new ScriptedAuthorityJournal();var ports=new ScriptedAllocatorPorts();await using var lease=Lease(41);using var cts=new CancellationTokenSource();cts.Cancel();await Assert.ThrowsAsync<OperationCanceledException>(async()=>await new GraphParticipantReservationCoordinatorV2(journal,ports,ports,ports,lease).ReserveAsync(x.Request,cts.Token));Assert.Equal(0,journal.ReadCalls);Assert.Equal(0,ports.SnapshotCalls);var afterCommand=Fixture(15);using var commandCancel=new CancellationTokenSource();var commandInner=Journal(afterCommand.Session);var commandJournal=new ScriptedAuthorityJournal{Inner=commandInner,OutcomeUnknownOnAppendCall=1,CancelAfterAppendCall=1,CancelSource=commandCancel};await Assert.ThrowsAsync<OperationCanceledException>(async()=>await new GraphParticipantReservationCoordinatorV2(commandJournal,ports,ports,ports,lease).ReserveAsync(afterCommand.Request,commandCancel.Token));Assert.Equal(1,commandJournal.AppendCalls);Assert.Equal(0,ports.ClaimCalls);var commandRead=Assert.IsType<ReadAuthorityRangeResultV1.Batch>(await commandInner.ReadAsync(new(afterCommand.Session,0,long.MaxValue,256,1_048_576)));Assert.Single(commandRead.Facts);var afterD27=Fixture(16);using var d27Cancel=new CancellationTokenSource();var d27Ports=CommittedPorts(41);d27Ports.ClaimHandler=request=>{d27Cancel.Cancel();return CandidateCommitted(request);};var d27Result=Assert.IsType<GraphParticipantReservationResultV2.OutcomeUnknown>(await new GraphParticipantReservationCoordinatorV2(Journal(afterD27.Session),d27Ports,d27Ports,d27Ports,lease).ReserveAsync(afterD27.Request,d27Cancel.Token));Assert.Equal("allocator-outcome-unknown",d27Result.SafeCode.ToString());Assert.Equal(1,d27Ports.ClaimCalls);var afterResult=Fixture(17);using var resultCancel=new CancellationTokenSource();var resultInner=Journal(afterResult.Session);var resultJournal=new ScriptedAuthorityJournal{Inner=resultInner,OutcomeUnknownOnAppendCall=2,CancelAfterAppendCall=2,CancelSource=resultCancel};var resultPorts=CommittedPorts(41);Assert.IsType<GraphParticipantReservationResultV2.Applied>(await new GraphParticipantReservationCoordinatorV2(resultJournal,resultPorts,resultPorts,resultPorts,lease).ReserveAsync(afterResult.Request,resultCancel.Token));Assert.Equal(2,resultJournal.AppendCalls);Assert.Equal(1,resultPorts.ClaimCalls);}
    [Fact] public async Task Returned_candidate_and_envelope_mutations_quarantine(){var x=Fixture(14);var journal=Journal(x.Session);var ports=CommittedPorts(54);ports.ClaimHandler=request=>{var good=Assert.IsType<GlobalParticipantAllocatorDurableClaimResultV1.Committed>(CandidateCommitted(request));return new GlobalParticipantAllocatorDurableClaimResultV1.Committed(good.Head,good.Sequence,new byte[]{9});};await using var lease=Lease(54);var result=Assert.IsType<GraphParticipantReservationResultV2.Quarantined>(await new GraphParticipantReservationCoordinatorV2(journal,ports,ports,ports,lease).ReserveAsync(x.Request,CancellationToken.None));Assert.Equal("returned-candidate-mismatch",result.SafeCode.ToString());Assert.Equal(1,ports.ClaimCalls);}
    [Fact] public void Capacity_page_record_byte_and_attempt_bounds_are_enforced(){var x=Fixture(11);Assert.Throws<ArgumentOutOfRangeException>(()=>new GraphParticipantReservationRequestV2(x.Request.ExactCanonicalCommandBytes,x.Plan,x.Catalog,x.Registration,x.Request.Correlation,default,0,1));Assert.Throws<ArgumentOutOfRangeException>(()=>new GraphParticipantReservationRequestV2(x.Request.ExactCanonicalCommandBytes,x.Plan,x.Catalog,x.Registration,x.Request.Correlation,default,1,536_870_913));}
    [Fact] public void All_safe_code_result_precedence_arms_are_exact(){Assert.Equal(7,typeof(GraphParticipantReservationResultV2).GetNestedTypes(System.Reflection.BindingFlags.NonPublic).Length);Assert.Equal(13,SafeCodes().Length);}
    [Fact] public void Cross_instance_race_restart_and_repeated_unknown_never_promote_follower(){var s=Fixture(12);var f=GraphParticipantReservationFoldV2.Create(s.Session);f.Apply(Envelope(s,1));var other=Fixture(13,s.Session);f.Apply(Envelope(other,2));f.Complete();for(var i=0;i<3;i++)Assert.IsType<GraphParticipantReservationFoldV2.Follower>(f.Elect(other.Operation));}

