    {var session=fixedSession??new(RuntimeGenerationId.FromValue(Id((byte)(seed+20))),LiveSessionId.FromValue(Id((byte)(seed+40))));var operation=OperationId.FromValue(Id(seed));var graph=GraphGenerationId.FromValue(Id((byte)(seed+60)));var descriptor=new LiveAudioParticipantDescriptorV1(new("factory"),OwnerSliceId.S2,AuthorityAxisId.Graph,[],[new CapacityDimensionId(1)],new DurationNs(1),new DurationNs(1),new DurationNs(1));var carrier=LiveAudioParticipantCatalogManifestV1.EncodeGraphParticipantAllocationDeclaration("factory",["b","a"],[1],["00000000000000000000000000000001"],[1],[1]);using var h=IncrementalHash.CreateHash(HashAlgorithmName.SHA256);h.AppendData("hpd-graph-participant-allocation-declaration-v1\0"u8);h.AppendData(carrier);var carrierHash=Hash256.FromBytes(h.GetHashAndReset());var registration=new LiveAudioParticipantFactoryRegistrationV1(typeof(GraphParticipantReservationCoordinatorV2Tests),"tests:factory",descriptor,carrier,carrierHash);var catalog=LiveAudioParticipantCatalogManifestV1.Create([registration]);var planHash=Hash256.Compute([(byte)(seed+1)]);var plan=new LiveAudioParticipantPlanV1(LiveAudioPlanId.FromValue(Id((byte)(seed+2))),[descriptor],[],planHash);var authority=ExpectedAuthorityVectorV1.Create(session,[new AuthorityAxisValueV1.Graph(graph)]);var body=new GraphParticipantReservationCommandBodyV2(operation,null,session.RuntimeGenerationId,graph,planHash,carrierHash,new("factory"),[new("a"),new("b")],new(ClockDomainId.FromValue(Id(80)),BootId.FromValue(Id(81)),1));var bytes=GraphParticipantReservationCodecsV2.Encode(new GraphParticipantReservationCommandV2(session,authority,GraphParticipantReservationCodecsV2.Encode(body)));var correlation=new CorrelationEnvelopeV1(TenantId.FromValue(Id(82)),operationId:operation);return(session,operation,plan,catalog,registration,new(bytes,plan,catalog,registration,correlation,default,32,1_000_000));}
