    private static GlobalParticipantAllocatorDurableClaimResultV1 CandidateCommitted(GlobalParticipantAllocatorDurableClaimRequestV1 request){Assert.True(GlobalParticipantAllocatorCodecsV1.TryDecodeOuter(request.ExactCanonicalRecordBytes,out var outer));Assert.True(GlobalParticipantAllocatorCodecsV1.TryDecodeBody(outer!.BodyBytes.ToArray(),out var body));var hash=GlobalParticipantAllocatorFactIdsV1.RecordHash(body!.AssignedPosition,body.PriorHead,request.FactId,outer.SourceSession,outer.SourceExpectedAuthority,outer.BodyBytes);return new GlobalParticipantAllocatorDurableClaimResultV1.Committed(new(body.AssignedPosition,hash),body.AssignedPosition.Sequence,request.ExactCanonicalRecordBytes);}
