    private static GlobalParticipantAllocatorRealmLeaseV1 Lease(byte seed){var id=GlobalParticipantAllocatorJournalId.FromValue(Id(seed));var hash=Hash256.Compute([seed]);return new(new(id,1,1,hash,default,GlobalParticipantAllocatorRealmManifestV1.ComputeManifestHash(id,1,1,hash,default)),new TestRealmCustody());}
