    private sealed class ScriptedAuthorityJournal : IAuthorityJournalV1
    {internal IAuthorityJournalV1? Inner{get;init;}internal int CommitThenOutcomeUnknown{get;set;}internal int OutcomeUnknownOnAppendCall{get;init;}internal int CancelAfterAppendCall{get;init;}internal CancellationTokenSource? CancelSource{get;init;}internal int ReadCalls{get;private set;}internal int AppendCalls{get;private set;}public ValueTask<ReadAuthorityRangeResultV1> ReadAsync(ReadAuthorityRangeV1 request,CancellationToken cancellationToken=default){ReadCalls++;return Inner is null?ValueTask.FromResult<ReadAuthorityRangeResultV1>(new ReadAuthorityRangeResultV1.Batch(request.Session,request.AfterExclusive,request.AfterExclusive,0,[],false)):Inner.ReadAsync(request,cancellationToken);}public async ValueTask<AppendAuthorityResultV1> AppendAsync(AppendAuthorityBatchV1 request,CancellationToken cancellationToken=default){AppendCalls++;if(Inner is null)return new AppendAuthorityResultV1.StoreUnavailable(new("x"));var committed=await Inner.AppendAsync(request,cancellationToken);if(CancelAfterAppendCall==AppendCalls)CancelSource!.Cancel();if(CommitThenOutcomeUnknown-->0||OutcomeUnknownOnAppendCall==AppendCalls)return new AppendAuthorityResultV1.OutcomeUnknown(request.Facts[0].Correlation.OperationId!.Value);return committed;}}
    private sealed class ScriptedAllocatorPorts : IGlobalParticipantAllocatorDurableClaimPortV1,IGlobalParticipantAllocatorReconciliationPortV1,IGlobalParticipantAllocatorDurableSnapshotPortV1
    {internal Queue<GlobalParticipantAllocatorDurableSnapshotResultV1> Snapshots{get;}=[];internal Func<GlobalParticipantAllocatorDurableSnapshotRequestV1,GlobalParticipantAllocatorDurableSnapshotResultV1>? SnapshotHandler{get;init;}internal Func<GlobalParticipantAllocatorDurableClaimRequestV1,GlobalParticipantAllocatorDurableClaimResultV1>? ClaimHandler{get;set;}internal Func<GlobalParticipantAllocatorReconcileRequestV1,GlobalParticipantAllocatorReconcileResultV1>? ReconcileHandler{get;set;}internal GlobalParticipantAllocatorDurableClaimRequestV1? LastClaim{get;set;}internal GlobalParticipantAllocatorReconcileRequestV1? LastReconcile{get;private set;}internal int SnapshotCalls{get;private set;}internal int ClaimCalls{get;private set;}internal int ReconcileCalls{get;private set;}public ValueTask<GlobalParticipantAllocatorDurableSnapshotResultV1> ReadAsync(GlobalParticipantAllocatorDurableSnapshotRequestV1 request,CancellationToken cancellationToken){SnapshotCalls++;return ValueTask.FromResult(SnapshotHandler is null?Snapshots.Dequeue():SnapshotHandler(request));}public ValueTask<GlobalParticipantAllocatorDurableClaimResultV1> ClaimAsync(GlobalParticipantAllocatorDurableClaimRequestV1 request,CancellationToken cancellationToken){ClaimCalls++;LastClaim=request;return ValueTask.FromResult(ClaimHandler!(request));}public ValueTask<GlobalParticipantAllocatorReconcileResultV1> ReconcileAsync(GlobalParticipantAllocatorReconcileRequestV1 request,CancellationToken cancellationToken){ReconcileCalls++;LastReconcile=request;return ValueTask.FromResult(ReconcileHandler!(request));}}
